DO $$ DECLARE d text; a text; BEGIN d:=pg_get_functiondef('public.save_trip(jsonb)'::regprocedure); IF strpos(d,' IF p?''advances''')=0 THEN RAISE EXCEPTION 'Advance section not found'; END IF; a:=substring(d FROM strpos(d,' IF p?''advances''')); a:=replace(a,E'    payment_status=CASE WHEN r?''payment_status'' THEN r->>''payment_status'' ELSE payment_status END,\n',''); a:=replace(a,'v_acct,nullif(r->>''reference'',''''),nullif(r->>''notes'',''''),coalesce(nullif(r->>''payment_status'',''''),''paid''));','v_acct,nullif(r->>''reference'',''''),nullif(r->>''notes'',''''));'); d:=substring(d FROM 1 FOR strpos(d,' IF p?''advances''')-1)||a; IF strpos(a,'payment_status=CASE')>0 OR strpos(a,',coalesce(nullif(r->>''payment_status''')>0 THEN RAISE EXCEPTION 'Advance repair incomplete'; END IF; EXECUTE d; END $$;